-------------------------------------------------------------------------------
-- User patterns
--
--  Saved patterns survive between sessions. Each one keeps its bar count and
--  its groove settings alongside the steps, so loading one restores the
--  pattern exactly as it was saved.
-------------------------------------------------------------------------------

local user_presets = {}

local function serialize_grid(bars)
  local parts = {}
  local total = bars * 16
  for i = 1, #DRUM_MAP do
    for s = 1, total do
      parts[#parts + 1] = tostring(grid[i][s] or 0)
    end
  end
  return table.concat(parts, ",")
end

local function deserialize_grid(data, bars)
  local total  = bars * 16
  local values = {}
  for v in data:gmatch("[^,]+") do values[#values + 1] = tonumber(v) or 0 end
  local idx = 1
  for i = 1, #DRUM_MAP do
    grid[i] = {}
    for s = 1, total do
      grid[i][s] = values[idx] or 0
      idx = idx + 1
    end
  end
end

-- Groove settings travel with a pattern, stored as "swing,timing,spread".
local function groove_to_string(g)
  return string.format("%d,%d,%d", g.swing or 0, g.h_t or 0, g.h_v or 0)
end

local function groove_from_string(s)
  if not s or s == "" then return nil end
  local a, b, c = s:match("^(%-?%d+),(%-?%d+),(%-?%d+)$")
  if not a then return nil end
  local function clamp(v, lo, hi) return math.max(lo, math.min(hi, tonumber(v))) end
  return { swing = clamp(a, 0, 100), h_t = clamp(b, 0, 100), h_v = clamp(c, 0, 80) }
end

local function save_user_presets()
  reaper.SetExtState(EXT_SECTION, "user_preset_count",
    tostring(#user_presets), true)
  for i, p in ipairs(user_presets) do
    reaper.SetExtState(EXT_SECTION, "user_preset_name_" .. i, p.name,  true)
    reaper.SetExtState(EXT_SECTION, "user_preset_bars_" .. i,
      tostring(p.bars), true)
    reaper.SetExtState(EXT_SECTION, "user_preset_data_" .. i, p.data,  true)
    if p.groove then
      reaper.SetExtState(EXT_SECTION, "user_preset_groove_" .. i,
        groove_to_string(p.groove), true)
    else
      reaper.DeleteExtState(EXT_SECTION, "user_preset_groove_" .. i, true)
    end
  end
  -- Clear any leftover slots beyond the current count
  for i = #user_presets + 1, #user_presets + 10 do
    reaper.DeleteExtState(EXT_SECTION, "user_preset_name_" .. i, true)
    reaper.DeleteExtState(EXT_SECTION, "user_preset_bars_" .. i, true)
    reaper.DeleteExtState(EXT_SECTION, "user_preset_data_" .. i, true)
    reaper.DeleteExtState(EXT_SECTION, "user_preset_groove_" .. i, true)
  end
end

local function load_user_presets()
  user_presets = {}
  local count = tonumber(
    reaper.GetExtState(EXT_SECTION, "user_preset_count")) or 0
  for i = 1, count do
    local name = reaper.GetExtState(EXT_SECTION, "user_preset_name_" .. i)
    local bars = tonumber(
      reaper.GetExtState(EXT_SECTION, "user_preset_bars_" .. i)) or 1
    local data = reaper.GetExtState(EXT_SECTION, "user_preset_data_" .. i)
    -- A pattern with no groove stored yields nil here.
    local groove = groove_from_string(
      reaper.GetExtState(EXT_SECTION, "user_preset_groove_" .. i))
    if name ~= "" and data ~= "" then
      local captured_data = data
      local captured_bars = bars
      user_presets[#user_presets + 1] = {
        name = name,
        bars = captured_bars,
        data = captured_data,
        groove = groove,
        func = function(_gs)
          init_grid(captured_bars * 16, true)
          deserialize_grid(captured_data, captured_bars)
        end,
      }
    end
  end
end

local function save_current_as_user_preset(name, bars, groove)
  name = name:match("^%s*(.-)%s*$")  -- trim whitespace
  if name == "" then return false, "Name cannot be empty." end
  for _, p in ipairs(user_presets) do
    if p.name == name then return false, "A preset named '" .. name .. "' already exists." end
  end
  local data = serialize_grid(bars)
  local captured_data = data
  local captured_bars = bars
  user_presets[#user_presets + 1] = {
    name = name,
    bars = bars,
    data = data,
    groove = groove,
    func = function(_gs)
      init_grid(captured_bars * 16, true)
      deserialize_grid(captured_data, captured_bars)
    end,
  }
  save_user_presets()
  return true, "Preset '" .. name .. "' saved."
end

local function delete_user_preset(idx)
  if idx < 1 or idx > #user_presets then return end
  table.remove(user_presets, idx)
  save_user_presets()
end

-- Copies the pattern to the clipboard as code that can be pasted straight
-- into the factory pattern list above.
local function export_to_clipboard(preset_name, bars, groove)
  preset_name = preset_name:match("^%s*(.-)%s*$")
  if preset_name == "" then preset_name = "My Pattern" end

  -- One line per active step
  local lines = {}
  local total = bars * 16
  for i = 1, #DRUM_MAP do
    for s = 1, total do
      local layer = to_layer(grid[i][s])
      if layer > 0 then
        lines[#lines + 1] = string.format("    set(%d, %d, %d)", i, s, layer)
      end
    end
  end

  -- Wrap it as a pattern entry
  local block = {}
  block[#block+1] = "  -- ======================================================"
  block[#block+1] = "  -- USER PRESET : " .. preset_name
  block[#block+1] = "  -- Bars   : " .. bars
  block[#block+1] = "  -- Saved  : " .. os.date("%Y-%m-%d %H:%M")
  block[#block+1] = "  -- ======================================================"
  block[#block+1] = "  { name = \"" .. preset_name .. "\","
  if groove then
    block[#block+1] = string.format(
      "    groove = { swing = %d, h_t = %d, h_v = %d },",
      groove.swing or 0, groove.h_t or 0, groove.h_v or 0)
  end
  block[#block+1] = "    func = function(gs)"
  block[#block+1] = "      init_grid(gs, true)"
  if #lines > 0 then
    for _, l in ipairs(lines) do block[#block+1] = l end
  else
    block[#block+1] = "      -- (empty pattern)"
  end
  block[#block+1] = "    end },"

  local result = table.concat(block, "\n")
  if not reaper.CF_SetClipboard then
    return nil, "The SWS extension is required to copy to the clipboard."
  end
  reaper.CF_SetClipboard(result)
  return result
end

load_user_presets()

-------------------------------------------------------------------------------
-- Target track
--
--  The track a pattern was written to is remembered for each project, so
--  generating still works after clicking elsewhere in REAPER. Items written
--  here are marked, which is how a regenerated pattern replaces the previous
--  one rather than piling on top of it.
-------------------------------------------------------------------------------

local PROJEXT  = "SK_DRUMS_GEN"
local ITEM_TAG = "P_EXT:SK_DRUMS_GEN"

local target_cache = { guid = nil, track = nil }

local function track_name(tr)
  local _, nm = reaper.GetSetMediaTrackInfo_String(tr, "P_NAME", "", false)
  if not nm or nm == "" then
    nm = "Track " .. math.floor(reaper.GetMediaTrackInfo_Value(tr, "IP_TRACKNUMBER"))
  end
  return nm
end

local function remember_track(tr)
  if not tr then return end
  local guid = reaper.GetTrackGUID(tr)
  target_cache.guid, target_cache.track = guid, tr
  reaper.SetProjExtState(0, PROJEXT, "last_track_guid", guid)
end

local function find_track_by_guid(guid)
  if not guid or guid == "" then return nil end
  for i = 0, reaper.CountTracks(0) - 1 do
    local tr = reaper.GetTrack(0, i)
    if reaper.GetTrackGUID(tr) == guid then return tr end
  end
  return nil
end

-- The remembered track of the current project, or nil if it was deleted.
local function remembered_track()
  local _, guid = reaper.GetProjExtState(0, PROJEXT, "last_track_guid")
  if not guid or guid == "" then return nil end
  local c = target_cache
  if c.guid == guid and c.track
     and reaper.ValidatePtr2(0, c.track, "MediaTrack*")
     and reaper.GetTrackGUID(c.track) == guid then
    return c.track
  end
  local tr = find_track_by_guid(guid)
  c.guid, c.track = guid, tr
  return tr
end

-- The track selected in REAPER, or failing that the remembered one.
local function target_track()
  local sel = reaper.GetSelectedTrack(0, 0)
  if sel then return sel, "selection" end
  local tr = remembered_track()
  if tr then return tr, "memory" end
  return nil, nil
end

-------------------------------------------------------------------------------
-- Autosave
--
--  The pattern being worked on is kept with the project, so closing the window
--  does not throw it away. It is written only when something actually changed,
--  and at most every couple of seconds, so simply opening the script and
--  looking around leaves the project untouched.
-------------------------------------------------------------------------------

local AUTOSAVE_KEY    = "last_state"
local AUTOSAVE_PERIOD = 2.0

local autosave_written = nil   -- last payload stored, to skip pointless writes
local autosave_checked = 0

-- "1;bars;swing,timing,spread;fill;steps"  (version first, so a later format
-- can be told apart from this one and simply ignored rather than misread)
local function state_to_string(st)
  return table.concat({
    "1",
    tostring(st.bars),
    groove_to_string(st),
    st.use_fill and "1" or "0",
    serialize_grid(st.bars),
  }, ";")
end

local function autosave(st, force)
  local now = reaper.time_precise()
  if not force and (now - autosave_checked) < AUTOSAVE_PERIOD then return end
  autosave_checked = now
  local payload = state_to_string(st)
  if payload == autosave_written then return end
  autosave_written = payload
  reaper.SetProjExtState(0, PROJEXT, AUTOSAVE_KEY, payload)
end

-- Restores the pattern saved with this project. Returns false when there is
-- nothing to restore, or when what is there cannot be read.
local function autoload(st)
  local _, payload = reaper.GetProjExtState(0, PROJEXT, AUTOSAVE_KEY)
  if not payload or payload == "" then return false end

  local ver, bars, groove, fill, data =
    payload:match("^(%d+);(%d+);([^;]*);([01]);(.*)$")
  if ver ~= "1" then return false end
  bars = tonumber(bars)
  if not bars or bars < 1 or data == "" then return false end

  st.bars = bars
  init_grid(bars * 16, true)
  deserialize_grid(data, bars)
  local g = groove_from_string(groove)
  if g then st.swing, st.h_t, st.h_v = g.swing, g.h_t, g.h_v end
  st.use_fill = (fill == "1")

  autosave_written = payload
  return true
end

-------------------------------------------------------------------------------
-- Writing the pattern to REAPER
-------------------------------------------------------------------------------

-- Auto-fill. It takes over the second half of this bar, and is offered only
-- once the pattern is at least that long. Change the bar number here alone.
local FILL_BAR   = 8
local FILL_START = (FILL_BAR - 1) * 16 + 9
local FILL_END   = FILL_BAR * 16

local function write_to_reaper(state)
  local track, src = target_track()
  if not track then
    return false, "No track selected, and none remembered in this project yet."
  end

  local start_pos = reaper.GetCursorPosition()
  local qn_offset = reaper.TimeMap2_timeToQN(0, start_pos)
  local end_time  = reaper.TimeMap2_QNToTime(0, qn_offset + (state.bars * 4))

  reaper.Undo_BeginBlock()

  -- Clear the way: selected items, plus patterns written here that overlap the
  -- new one. Moving the edit cursor elsewhere therefore lays a second pattern
  -- further along instead of wiping the first.
  for i = reaper.CountTrackMediaItems(track) - 1, 0, -1 do
    local item = reaper.GetTrackMediaItem(track, i)
    local drop = reaper.IsMediaItemSelected(item)
    if not drop then
      local _, tag = reaper.GetSetMediaItemInfo_String(item, ITEM_TAG, "", false)
      if tag == "1" then
        local p = reaper.GetMediaItemInfo_Value(item, "D_POSITION")
        local l = reaper.GetMediaItemInfo_Value(item, "D_LENGTH")
        if p < end_time and (p + l) > start_pos then drop = true end
      end
    end
    if drop then reaper.DeleteTrackMediaItem(track, item) end
  end

  local item = reaper.CreateNewMIDIItemInProj(track, start_pos, end_time, false)
  reaper.GetSetMediaItemInfo_String(item, ITEM_TAG, "1", true)
  reaper.SetMediaItemSelected(item, true)
  local take = reaper.GetActiveTake(item)
  reaper.MIDI_DisableSort(take)

  for i = 1, #DRUM_MAP do
    local inst = DRUM_MAP[i]
    for s = 1, state.bars * 16 do
      local layer = to_layer(grid[i][s])

      -- Auto-fill takes over the second half of the fill bar
      if state.use_fill and state.bars >= FILL_BAR
         and s >= FILL_START and s <= FILL_END then
        layer = 0
        if inst.id == "snare"   or inst.id == "tom_high"
        or inst.id == "tom_low" or inst.id == "rimshot" then
          if math.random() > 0.65 then
            layer = math.min(5, 2 + math.floor((s - (FILL_START - 1)) / 2))
          end
        end
        if s == FILL_END then
          if     inst.id == "kick"       then layer = 5
          elseif inst.id == "snare"
              or inst.id == "hihat_open" then
            layer = math.random() > 0.5 and 5 or 4
          end
        end
      end

      if layer > 0 then
        local pos_qn = (s - 1) * 0.25
        if s % 2 == 0 then
          pos_qn = pos_qn + ((state.swing / 100) * 0.083)
        end
        local ppq = math.floor(pos_qn * 960) + math.random(-state.h_t, state.h_t)
        local vel = vel_from_layer(layer, state.h_v)
        if inst.id == "hihat_closed" and layer <= 2 then
          vel = math.max(1, vel - 10)
        end
        reaper.MIDI_InsertNote(take, false, false, ppq, ppq + 120, 0,
          inst.note, vel, true)
      end
    end
  end
  reaper.MIDI_Sort(take)
  remember_track(track)
  reaper.Undo_EndBlock("SK Drums Generator: generate pattern", -1)
  reaper.UpdateArrange()

  return true, ("Written to \"%s\"%s."):format(
    track_name(track), (src == "memory") and "  (remembered track)" or "")
end

-------------------------------------------------------------------------------
-- Transport and note preview
--
--  PREVIEW sets the target track to All MIDI Inputs, arms it and turns input
--  monitoring on. The note buttons in the mapping panel then play through
--  whatever sampler sits on that track. Toggling PREVIEW off puts the track
--  back exactly as it was found.
-------------------------------------------------------------------------------

local REC_INPUT_ALL_MIDI = 4096 | (63 << 5) | 0  -- All MIDI Inputs, all channels

local PREVIEW_VEL = 100    -- velocity used when auditioning a note
local PREVIEW_LEN = 0.30   -- how long an auditioned note is held, in seconds

local pending_notes = {}

-- Plays a note now and queues its release, so a sustaining sampler
-- does not hang on it.
local function preview_note(note)
  if not note or note < 0 or note > 127 then return end
  reaper.StuffMIDIMessage(0, 0x90, note, PREVIEW_VEL)  -- note-on, channel 1
  pending_notes[#pending_notes + 1] = {
    note = note, deadline = reaper.time_precise() + PREVIEW_LEN }
end

local function flush_pending_notes(force)
  local now = reaper.time_precise()
  for i = #pending_notes, 1, -1 do
    if force or now >= pending_notes[i].deadline then
      reaper.StuffMIDIMessage(0, 0x80, pending_notes[i].note, 0)  -- note-off
      table.remove(pending_notes, i)
    end
  end
end

-- Remembers the track PREVIEW touched, and its settings from before.
local preview = { on = false, track = nil, rec_input = nil, rec_arm = nil, rec_mon = nil }

local function preview_off()
  local tr = preview.track
  if tr and reaper.ValidatePtr(tr, "MediaTrack*") then
    if preview.rec_input then reaper.SetMediaTrackInfo_Value(tr, "I_RECINPUT", preview.rec_input) end
    if preview.rec_arm   then reaper.SetMediaTrackInfo_Value(tr, "I_RECARM",   preview.rec_arm)   end
    if preview.rec_mon   then reaper.SetMediaTrackInfo_Value(tr, "I_RECMON",   preview.rec_mon)   end
  end
  flush_pending_notes(true)
  preview.on, preview.track = false, nil
  preview.rec_input, preview.rec_arm, preview.rec_mon = nil, nil, nil
end

local function preview_on()
  local tr, src = target_track()
  if not tr then return false, "No track selected, and none remembered in this project yet." end
  preview.track     = tr
  preview.rec_input = reaper.GetMediaTrackInfo_Value(tr, "I_RECINPUT")
  preview.rec_arm   = reaper.GetMediaTrackInfo_Value(tr, "I_RECARM")
  preview.rec_mon   = reaper.GetMediaTrackInfo_Value(tr, "I_RECMON")
  reaper.SetMediaTrackInfo_Value(tr, "I_RECINPUT", REC_INPUT_ALL_MIDI)
  reaper.SetMediaTrackInfo_Value(tr, "I_RECARM",   1)
  reaper.SetMediaTrackInfo_Value(tr, "I_RECMON",   1)  -- needed to hear the track's FX
  preview.on = true
  return true, ("Track armed: \"%s\" on All MIDI Inputs%s."):format(
    track_name(tr), (src == "memory") and "  (remembered track)" or "")
end

-- Drop the preview if its track has been deleted in the meantime.
local function preview_validate()
  if preview.on and (not preview.track
     or not reaper.ValidatePtr(preview.track, "MediaTrack*")) then
    preview.on, preview.track = false, nil
  end
end

local function is_playing() return (reaper.GetPlayState() & 1) == 1 end

local function transport_toggle()
  if is_playing() then reaper.CSurf_OnStop() else reaper.CSurf_OnPlay() end
end

local BPM_MIN, BPM_MAX = 1.0, 960.0

local function set_bpm(v)
  v = tonumber(v)
  if not v then return end
  reaper.SetCurrentBPM(0, math.max(BPM_MIN, math.min(BPM_MAX, v)), true)
end

