local NOTE_NAMES = {"C","C#","D","D#","E","F","F#","G","G#","A","A#","B"}
local function note_to_name(n)
  if n < 0 or n > 127 then return "?" end
  return NOTE_NAMES[(n % 12) + 1] .. tostring(math.floor(n / 12) - 2)
end

