local function pushTheme()
  for _, c in ipairs(THEME_COLORS) do reaper.ImGui_PushStyleColor(ctx, c[1], c[2]) end
  reaper.ImGui_PushStyleVar(ctx, reaper.ImGui_StyleVar_WindowRounding(),  8)
