-- Picks dark or light text, whichever stays readable on the given background.
local function textOn(rgba)
  local r = (rgba >> 24) & 0xFF
  local g = (rgba >> 16) & 0xFF
  local b = (rgba >>  8) & 0xFF
  local brightness = (0.299 * r + 0.587 * g + 0.114 * b) / 255
  return (brightness > 0.55) and COL_INK or COL_PAPER
end

-- Brightens or darkens a colour, keeping its transparency.
local function shade(rgba, f)
  local r = math.min(255, math.floor(((rgba >> 24) & 0xFF) * f))
  local g = math.min(255, math.floor(((rgba >> 16) & 0xFF) * f))
  local b = math.min(255, math.floor(((rgba >>  8) & 0xFF) * f))
  return (r << 24) | (g << 16) | (b << 8) | (rgba & 0xFF)
end

-- The small coloured dot identifying a drum element.
local function colorDot(rgba, radius, h)
  radius = radius or 4
  local dl   = reaper.ImGui_GetWindowDrawList(ctx)
  local x, y = reaper.ImGui_GetCursorScreenPos(ctx)
  h = h or reaper.ImGui_GetTextLineHeight(ctx)
  reaper.ImGui_DrawList_AddCircleFilled(dl, x + radius, y + h * 0.5, radius, rgba)
  reaper.ImGui_Dummy(ctx, radius * 2, h)
end

-- A square button holding a drawn symbol: 'play', 'stop' or 'circle'.
-- When active it turns amber.
local function iconButton(id, kind, size, active)
  local x, y    = reaper.ImGui_GetCursorScreenPos(ctx)
  local clicked = reaper.ImGui_InvisibleButton(ctx, id, size, size)
  local hovered = reaper.ImGui_IsItemHovered(ctx)
  local held    = reaper.ImGui_IsItemActive(ctx)
  local dl      = reaper.ImGui_GetWindowDrawList(ctx)

  local bg
  if active then
    bg = held and COL_ACCENT_A or (hovered and COL_ACCENT_H or COL_ACCENT)
  else
    bg = held and 0x474D58FF or (hovered and 0x3B404AFF or 0x30343BFF)
  end
  reaper.ImGui_DrawList_AddRectFilled(dl, x, y, x + size, y + size, bg, 6)

  local fg     = active and COL_INK or COL_PAPER
  local cx, cy = x + size * 0.5, y + size * 0.5
  local r      = size * 0.26

  if kind == 'play' then
    -- Sitting slightly right: a triangle looks off-centre when truly centred.
    reaper.ImGui_DrawList_AddTriangleFilled(dl,
      cx - r * 0.70, cy - r,
      cx - r * 0.70, cy + r,
      cx + r * 0.95, cy, fg)
  elseif kind == 'stop' then
    local h = r * 0.78
    reaper.ImGui_DrawList_AddRectFilled(dl, cx - h, cy - h, cx + h, cy + h, fg, 1)
  else -- 'circle'
    reaper.ImGui_DrawList_AddCircleFilled(dl, cx, cy, r * 0.85, fg)
  end

  return clicked
end

-- Shortest gap between two velocity steps made with the wheel. Lower it if the
-- wheel feels sluggish, raise it if one notch moves more than one layer.
local WHEEL_STEP_GAP = 0.08

local state = {
  bars            = 1,
  h_t             = 0,   -- timing spread, in MIDI ticks (0 = dead on the grid)
  h_v             = 0,   -- velocity spread around the layer range (0 = exact)
  swing           = 0,
  current_page    = 0,
  use_fill        = false,
  selected_factory = 1,  -- 0 when a user pattern is loaded instead
  selected_user    = 0,  -- 0 when none is selected
  vel_edit_mode   = false,
}

local _  -- throwaway for the returns we ignore

local ui_save_name     = ""
local ui_save_msg      = ""
local ui_save_msg_time = 0
local ui_clipboard_msg = ""
local ui_clipboard_time = 0
local ui_export_name   = ""
local ui_edit_name     = nil           -- drum element being renamed on the grid
local ui_edit_focus    = false
local ui_status        = ""
local ui_status_time   = 0
local ui_bpm           = nil
local ui_wheel_time    = 0     -- when the wheel last moved a layer
local ui_wheel_cell    = nil   -- which step it moved

local note_inputs = {}
for i, inst in ipairs(DRUM_MAP) do note_inputs[i] = inst.note end

init_grid(16, true)

-- Pick the pattern back up where it was left in this project. When there is
-- nothing to restore, remember the empty pattern as-is so that opening the
-- script and closing it again writes nothing.
if not autoload(state) then
  autosave_written = state_to_string(state)
end

-- Shows a message for three seconds.
local function feedback(msg, is_clipboard)
  if is_clipboard then
    ui_clipboard_msg  = msg
    ui_clipboard_time = reaper.time_precise()
  else
    ui_save_msg       = msg
    ui_save_msg_time  = reaper.time_precise()
  end
end

local first_frame = true

local function loop()
  flush_pending_notes(false)
  preview_validate()
  autosave(state)

  -- Pick up the saved notes on the first frame, before the fields can report a
  -- change that never happened.
  if first_frame then
    for i, inst in ipairs(DRUM_MAP) do note_inputs[i] = inst.note end
    first_frame = false
  end

  -- Let timed messages expire
  if ui_save_msg ~= "" and reaper.time_precise() - ui_save_msg_time > 3 then
    ui_save_msg = ""
  end
  if ui_clipboard_msg ~= "" and reaper.time_precise() - ui_clipboard_time > 3 then
    ui_clipboard_msg = ""
  end
  if ui_status ~= "" and reaper.time_precise() - ui_status_time > 3 then
    ui_status = ""
  end

  pushTheme()
  reaper.ImGui_SetNextWindowSize(ctx, 680, 900, reaper.ImGui_Cond_FirstUseEver())
  local visible, open = reaper.ImGui_Begin(ctx,
    "SK Drums Generator",
    true, reaper.ImGui_WindowFlags_AlwaysAutoResize())

  if visible then

    -- Title
    PushFont(fontTitle, FONT_TITLE)
    reaper.ImGui_PushStyleColor(ctx, reaper.ImGui_Col_Text(), COL_ACCENT)
    reaper.ImGui_Text(ctx, "SK DRUMS GENERATOR")
    reaper.ImGui_PopStyleColor(ctx)
    PopFont()
    reaper.ImGui_Separator(ctx)

    -- Bars, pattern tools and session tempo
    reaper.ImGui_SetNextItemWidth(ctx, 110)
    local chg, nb = reaper.ImGui_InputInt(ctx, "Bars", state.bars)
    if chg and nb > 0 then
      state.bars = nb
      init_grid(state.bars * 16, false)
    end

    reaper.ImGui_SameLine(ctx)
    if reaper.ImGui_Button(ctx, "DUPLICATE") then
      local old  = state.bars
      state.bars = old * 2
      init_grid(state.bars * 16, false)
      for i = 1, #DRUM_MAP do
        for s = 1, old * 16 do
          grid[i][s + (old * 16)] = grid[i][s]
        end
      end
    end

    reaper.ImGui_SameLine(ctx)
    if reaper.ImGui_Button(ctx, "RESET") then init_grid(state.bars * 16, true) end

    reaper.ImGui_SameLine(ctx)
    if reaper.ImGui_Button(ctx, "RANDOM") then
      randomize_intelligent(state.current_page, state.current_page)
    end

    -- The tempo field follows REAPER unless you are typing in it.
    reaper.ImGui_SameLine(ctx, 0, 24)
    reaper.ImGui_TextDisabled(ctx, "BPM")
    reaper.ImGui_SameLine(ctx, 0, 6)

    local bpm_live = reaper.Master_GetTempo()
    if ui_bpm == nil then ui_bpm = bpm_live end

    reaper.ImGui_SetNextItemWidth(ctx, 78)
    local bchg, bval = reaper.ImGui_InputDouble(ctx, "##bpm", ui_bpm, 0, 0, "%.2f")
    if bchg then ui_bpm = bval end
    -- Applied on Enter or when the field is left, never mid-typing.
    if reaper.ImGui_IsItemDeactivatedAfterEdit(ctx) then
      set_bpm(ui_bpm)
      ui_bpm = reaper.Master_GetTempo()
    elseif not reaper.ImGui_IsItemActive(ctx) then
      ui_bpm = bpm_live
    end

    reaper.ImGui_SameLine(ctx, 0, 4)
    if reaper.ImGui_Button(ctx, "-##bpmdn", 26, 0) then
      set_bpm(bpm_live - 1)
      ui_bpm = reaper.Master_GetTempo()
    end
    reaper.ImGui_SameLine(ctx, 0, 4)
    if reaper.ImGui_Button(ctx, "+##bpmup", 26, 0) then
      set_bpm(bpm_live + 1)
      ui_bpm = reaper.Master_GetTempo()
    end

    reaper.ImGui_Separator(ctx)

    -- Factory patterns
    sectionLabel("FACTORY PRESETS")
    reaper.ImGui_SetNextItemWidth(ctx, 300)
    local factory_label = state.selected_factory > 0
      and FACTORY_PRESETS[state.selected_factory].name
      or  "-- user preset active --"
    if reaper.ImGui_BeginCombo(ctx, "##factory", factory_label) then
      for i, p in ipairs(FACTORY_PRESETS) do
        if reaper.ImGui_Selectable(ctx, p.name, i == state.selected_factory) then
          state.selected_factory = i
          state.selected_user    = 0
          p.func(state.bars * 16)
          if p.groove then
            state.swing = p.groove.swing
            state.h_t   = p.groove.h_t
            state.h_v   = p.groove.h_v
          end
        end
      end
      reaper.ImGui_EndCombo(ctx)
    end

    -- Your own patterns

    local user_header_label = #user_presets == 0
      and "USER PRESETS  (none saved)"
      or  "USER PRESETS  (" .. #user_presets .. " saved)"

    if reaper.ImGui_CollapsingHeader(ctx, user_header_label) then

      reaper.ImGui_Spacing(ctx)

      if #user_presets == 0 then
        reaper.ImGui_TextDisabled(ctx, "  No user presets saved yet.")
      else
        reaper.ImGui_SetNextItemWidth(ctx, 300)
        local user_label = state.selected_user > 0
          and user_presets[state.selected_user].name
          or  "-- select a user preset --"
        if reaper.ImGui_BeginCombo(ctx, "##user", user_label) then
          for i, p in ipairs(user_presets) do
            local is_sel = (i == state.selected_user)
            if reaper.ImGui_Selectable(ctx, p.name, is_sel) then
              state.selected_user    = i
              state.selected_factory = 0
            end
          end
          reaper.ImGui_EndCombo(ctx)
        end

        reaper.ImGui_SameLine(ctx)
        if reaper.ImGui_Button(ctx, "LOAD") then
          if state.selected_user > 0 then
            local p = user_presets[state.selected_user]
            state.bars = p.bars
            init_grid(p.bars * 16, true)
            p.func(p.bars * 16)
            -- A pattern with no groove stored leaves the sliders alone.
            if p.groove then
              state.swing = p.groove.swing
              state.h_t   = p.groove.h_t
              state.h_v   = p.groove.h_v
            end
            feedback("Loaded: " .. p.name)
          end
        end

        reaper.ImGui_SameLine(ctx)
        reaper.ImGui_PushStyleColor(ctx, reaper.ImGui_Col_Button(), 0x882222FF)
        if reaper.ImGui_Button(ctx, "DELETE") then
          if state.selected_user > 0 then
            local name = user_presets[state.selected_user].name
            delete_user_preset(state.selected_user)
            state.selected_user = 0
            feedback("Deleted: " .. name)
          end
        end
        reaper.ImGui_PopStyleColor(ctx)
      end

      if ui_save_msg ~= "" then
        reaper.ImGui_SameLine(ctx)
        reaper.ImGui_TextColored(ctx, 0x88FF88FF, ui_save_msg)
      end

      reaper.ImGui_Separator(ctx)

      reaper.ImGui_Text(ctx, "Save current pattern as user preset :")
      reaper.ImGui_SetNextItemWidth(ctx, 220)
      _, ui_save_name = reaper.ImGui_InputText(ctx, "##savename", ui_save_name)
      reaper.ImGui_SameLine(ctx)
      reaper.ImGui_PushStyleColor(ctx, reaper.ImGui_Col_Button(), 0x226622FF)
      if reaper.ImGui_Button(ctx, "SAVE PRESET") then
        local ok, msg = save_current_as_user_preset(ui_save_name, state.bars,
          { swing = state.swing, h_t = state.h_t, h_v = state.h_v })
        feedback(msg)
        if ok then ui_save_name = "" end
      end
      reaper.ImGui_PopStyleColor(ctx)

      reaper.ImGui_Separator(ctx)

      reaper.ImGui_Text(ctx, "Export to clipboard (paste into script source) :")
      reaper.ImGui_SetNextItemWidth(ctx, 220)
      _, ui_export_name = reaper.ImGui_InputText(ctx, "##exportname", ui_export_name)
      reaper.ImGui_SameLine(ctx)
      reaper.ImGui_PushStyleColor(ctx, reaper.ImGui_Col_Button(), 0x225566FF)
      if reaper.ImGui_Button(ctx, "COPY LUA CODE") then
        local ok, err = export_to_clipboard(ui_export_name, state.bars,
          { swing = state.swing, h_t = state.h_t, h_v = state.h_v })
        feedback(ok and "Lua code copied to clipboard!" or err, true)
      end
      reaper.ImGui_PopStyleColor(ctx)

      if ui_clipboard_msg ~= "" then
        reaper.ImGui_SameLine(ctx)
        reaper.ImGui_TextColored(ctx, 0xFFDD44FF, ui_clipboard_msg)
      end

      reaper.ImGui_TextDisabled(ctx,
        "  Paste the copied code inside FACTORY_PRESETS in the script source.")

      reaper.ImGui_Spacing(ctx)

    end  -- end CollapsingHeader USER PRESETS

    -- Note and name assignment

    if reaper.ImGui_CollapsingHeader(ctx,
        "MIDI MAPPING##midi_mapping") then

      reaper.ImGui_Spacing(ctx)

      -- ARM button, sized to the height of the text buttons beside it so the
      -- row lines up. Amber when the track is armed, grey when not. Arming
      -- routes All MIDI Inputs to the target track, so the note buttons below
      -- play through its sampler.
      local arm_h = reaper.ImGui_GetFrameHeight(ctx)
      if iconButton("##arm", 'circle', arm_h, preview.on) then
        if preview.on then
          preview_off()
          ui_status = "Track disarmed, restored."
        else
          local ok, msg = preview_on()
          ui_status = msg
        end
        ui_status_time = reaper.time_precise()
      end
      reaper.ImGui_SameLine(ctx)

      reaper.ImGui_PushStyleColor(ctx, reaper.ImGui_Col_Button(), 0x226622FF)
      if reaper.ImGui_Button(ctx, "SAVE MAPPING") then
        save_mapping()
      end
      reaper.ImGui_PopStyleColor(ctx)
      reaper.ImGui_SameLine(ctx)

      reaper.ImGui_PushStyleColor(ctx, reaper.ImGui_Col_Button(), 0x884400FF)
      if reaper.ImGui_Button(ctx, "RESET MAPPING") then
        reset_mapping()
        for i, inst in ipairs(DRUM_MAP) do note_inputs[i] = inst.note end
      end
      reaper.ImGui_PopStyleColor(ctx)
      reaper.ImGui_SameLine(ctx)
      reaper.ImGui_TextDisabled(ctx, "arm the track, then click a note to hear it")

      reaper.ImGui_Spacing(ctx)

      reaper.ImGui_Spacing(ctx)
      reaper.ImGui_TextDisabled(ctx,
        "  Rename freely. Click a note name to audition it through the track's FX.")
      reaper.ImGui_Spacing(ctx)

      local cols_per_row = 2
      for i, inst in ipairs(DRUM_MAP) do
        if (i - 1) % cols_per_row ~= 0 then reaper.ImGui_SameLine(ctx, 0, 20) end
        reaper.ImGui_PushID(ctx, 9000 + i)
        reaper.ImGui_BeginGroup(ctx)

        colorDot(inst.color, 5, reaper.ImGui_GetFrameHeight(ctx))
        reaper.ImGui_SameLine(ctx, 0, 6)

        -- Renaming here also renames the element on the grid
        reaper.ImGui_SetNextItemWidth(ctx, 90)
        local _, nval = reaper.ImGui_InputText(ctx, "##name", inst.name)
        if nval ~= inst.name then DRUM_MAP[i].name = nval:sub(1, NAME_MAX) end
        if reaper.ImGui_IsItemDeactivatedAfterEdit(ctx) then
          DRUM_MAP[i].name = sanitize_name(DRUM_MAP[i].name) or DEFAULT_NAMES[i]
        end
        reaper.ImGui_SameLine(ctx, 0, 6)

        reaper.ImGui_SetNextItemWidth(ctx, 92)
        local changed, new_val = reaper.ImGui_InputInt(ctx, "##note", note_inputs[i])
        if changed then
          new_val          = math.max(0, math.min(127, new_val))
          note_inputs[i]   = new_val
          DRUM_MAP[i].note = new_val
        end
        reaper.ImGui_SameLine(ctx, 0, 6)

        -- Plays the note through the track's sampler
        if reaper.ImGui_Button(ctx, note_to_name(note_inputs[i]), 48, 0) then
          preview_note(note_inputs[i])
          if not preview.on then
            ui_status      = "Arm the track first (round button) to hear the note."
            ui_status_time = reaper.time_precise()
          end
        end

        reaper.ImGui_EndGroup(ctx)
        reaper.ImGui_PopID(ctx)
      end

      reaper.ImGui_Spacing(ctx)

    end  -- end CollapsingHeader MIDI MAPPING

    -- Velocity mode and auto-fill
    if state.vel_edit_mode then
      if accentButton("VELOCITY MODE  [ON]", 190, 0) then
        state.vel_edit_mode = false
      end
    else
      if reaper.ImGui_Button(ctx, "VELOCITY MODE [OFF]", 190, 0) then
        state.vel_edit_mode = true
      end
    end

    reaper.ImGui_SameLine(ctx)
    local can_fill = state.bars >= FILL_BAR
    if not can_fill then reaper.ImGui_BeginDisabled(ctx) end
    _, state.use_fill = reaper.ImGui_Checkbox(ctx, "AUTO-FILL BAR " .. FILL_BAR, state.use_fill)
    if not can_fill then reaper.ImGui_EndDisabled(ctx) end

    reaper.ImGui_SameLine(ctx)
    reaper.ImGui_TextDisabled(ctx,
      state.vel_edit_mode
        and "mouse wheel over a step sets its velocity"
        or "click = on/off")

    reaper.ImGui_Separator(ctx)

    -- One button per bar
    for p = 0, state.bars - 1 do
      if p > 0 and p % 8 ~= 0 then reaper.ImGui_SameLine(ctx) end
      local is_sel = (state.current_page == p)
      if is_sel then
        reaper.ImGui_PushStyleColor(ctx, reaper.ImGui_Col_Button(), COL_ACCENT)
        reaper.ImGui_PushStyleColor(ctx, reaper.ImGui_Col_Text(),   COL_INK)
      end
      if reaper.ImGui_Button(ctx, tostring(p + 1), 35, 25) then
        state.current_page = p
      end
      if is_sel then reaper.ImGui_PopStyleColor(ctx, 2) end
    end

    -- The step grid
    -- Widen the left column if an element has been given a long name.
    local inst_col_w = 84
    for _, inst in ipairs(DRUM_MAP) do
      local tw = reaper.ImGui_CalcTextSize(ctx, inst.name)
      if tw + 30 > inst_col_w then inst_col_w = tw + 30 end
    end

    if reaper.ImGui_BeginTable(ctx, "grid", 17,
        reaper.ImGui_TableFlags_Borders() | reaper.ImGui_TableFlags_RowBg()) then
      reaper.ImGui_TableSetupColumn(ctx, "INST",
        reaper.ImGui_TableColumnFlags_WidthFixed(), inst_col_w)
      for s = 1, 16 do
        reaper.ImGui_TableSetupColumn(ctx, "",
          reaper.ImGui_TableColumnFlags_WidthFixed(), 25)
      end

      reaper.ImGui_TableNextRow(ctx)
      reaper.ImGui_TableSetColumnIndex(ctx, 0)
      reaper.ImGui_Text(ctx, "BEAT")
      for s = 1, 16 do
        reaper.ImGui_TableSetColumnIndex(ctx, s)
        if s % 4 == 1 then reaper.ImGui_TextColored(ctx, COL_ACCENT, "|")
        else reaper.ImGui_Text(ctx, ".") end
      end

      for i = 1, #DRUM_MAP do
        reaper.ImGui_TableNextRow(ctx)
        reaper.ImGui_TableSetColumnIndex(ctx, 0)
        if ui_edit_name == i then
          -- Renaming here also renames the element in the mapping panel.
          reaper.ImGui_PushID(ctx, 7000 + i)
          if ui_edit_focus then
            reaper.ImGui_SetKeyboardFocusHere(ctx)
            ui_edit_focus = false
          end
          reaper.ImGui_SetNextItemWidth(ctx, inst_col_w - 6)
          local entered, v = reaper.ImGui_InputText(ctx, "##gridname", DRUM_MAP[i].name,
              reaper.ImGui_InputTextFlags_EnterReturnsTrue()
            | reaper.ImGui_InputTextFlags_AutoSelectAll())
          DRUM_MAP[i].name = v:sub(1, NAME_MAX)
          if entered or reaper.ImGui_IsItemDeactivated(ctx) then
            DRUM_MAP[i].name = sanitize_name(DRUM_MAP[i].name) or DEFAULT_NAMES[i]
            save_mapping()
            ui_edit_name = nil
          end
          reaper.ImGui_PopID(ctx)
        else
          colorDot(DRUM_MAP[i].color)
          reaper.ImGui_SameLine(ctx, 0, 5)
          reaper.ImGui_Text(ctx, DRUM_MAP[i].name)
          if reaper.ImGui_IsItemHovered(ctx)
             and reaper.ImGui_IsMouseDoubleClicked(ctx, reaper.ImGui_MouseButton_Left()) then
            ui_edit_name  = i
            ui_edit_focus = true
          end
        end

        for s = 1, 16 do
          local step  = (state.current_page * 16) + s
          local layer = to_layer(grid[i][step])
          reaper.ImGui_TableSetColumnIndex(ctx, s)
          reaper.ImGui_PushID(ctx, (i * 100000) + step)

          -- Cell colour follows the velocity layer, matching the legend.
          local btn_col, txt_col
          if layer == 0 then
            btn_col = (s % 4 == 1) and COL_CELL_OFF_ACC or COL_CELL_OFF
            txt_col = COL_PAPER
          else
            btn_col = VEL_COLORS[layer]
            txt_col = textOn(btn_col)
          end

          reaper.ImGui_PushStyleColor(ctx, reaper.ImGui_Col_Button(),        btn_col)
          reaper.ImGui_PushStyleColor(ctx, reaper.ImGui_Col_ButtonHovered(), shade(btn_col, 1.30))
          reaper.ImGui_PushStyleColor(ctx, reaper.ImGui_Col_ButtonActive(),  shade(btn_col, 0.80))
          reaper.ImGui_PushStyleColor(ctx, reaper.ImGui_Col_Text(),          txt_col)
          local label = (layer > 0) and (tostring(layer) .. "##b") or "##c"
            if reaper.ImGui_Button(ctx, label, 25, 25) then
               if state.vel_edit_mode then
              grid[i][step] = (layer + 1) % 6
              else
               grid[i][step] = (layer == 0) and 3 or 0
            end
          end
            if state.vel_edit_mode and reaper.ImGui_IsItemHovered(ctx) then
              local wheel = reaper.ImGui_GetMouseWheel(ctx)
              if wheel ~= 0 then
                -- Only the direction is used, never the amount. How much a
                -- wheel reports for one notch is not the same from one machine
                -- to the next, and a quick flick can report dozens of units at
                -- once, so reading the amount would make a step mean something
                -- different on every desk. Spacing steps out in time behaves
                -- the same everywhere: one notch moves one layer, and a flick
                -- moves one layer instead of slamming to the end.
                local cell = (i * 100000) + step
                local now  = reaper.time_precise()
                if ui_wheel_cell ~= cell
                   or (now - ui_wheel_time) >= WHEEL_STEP_GAP then
                  ui_wheel_cell, ui_wheel_time = cell, now
                  local dir = (wheel > 0) and 1 or -1
                  grid[i][step] = math.max(0, math.min(5, layer + dir))
                end
              end
            end
          reaper.ImGui_PopStyleColor(ctx, 4)
          reaper.ImGui_PopID(ctx)
        end
      end
      reaper.ImGui_EndTable(ctx)
    end

    -- Velocity legend
    reaper.ImGui_TextDisabled(ctx, "Layers : ")
    for i = 1, 5 do
      reaper.ImGui_SameLine(ctx)
      reaper.ImGui_TextColored(ctx, VEL_COLORS[i], i .. "-" .. VEL_LAYERS[i].label)
    end
    reaper.ImGui_NewLine(ctx)

    -- Groove
    sectionLabel("GROOVE & HUMANIZATION")
    reaper.ImGui_SetNextItemWidth(ctx, 130)
    _, state.swing = reaper.ImGui_SliderInt(ctx, "Swing",   state.swing, 0, 100)
    reaper.ImGui_SameLine(ctx)
    reaper.ImGui_SetNextItemWidth(ctx, 130)
    _, state.h_t   = reaper.ImGui_SliderInt(ctx, "Timing",  state.h_t,   0, 100)
    reaper.ImGui_SameLine(ctx)
    reaper.ImGui_SetNextItemWidth(ctx, 130)
    _, state.h_v   = reaper.ImGui_SliderInt(ctx, "Var.Vel", state.h_v,   0, 80)

    -- Transport, preview and generate
    reaper.ImGui_Dummy(ctx, 0, 8)

    local ACTION_H = 45

    -- Follows REAPER's transport, so it stays right if you use the spacebar.
    local playing = is_playing()
    if iconButton("##transport", playing and 'stop' or 'play', ACTION_H, playing) then
      transport_toggle()
    end
    reaper.ImGui_SameLine(ctx)

    PushFont(fontBtn, FONT_BTN)
    if accentButton("GENERATE & REPLACE", -1, ACTION_H) then
      local _, msg = write_to_reaper(state)
      ui_status      = msg
      ui_status_time = reaper.time_precise()
    end
    PopFont()

    -- Where the pattern will be written.
    local tt = target_track()
    if tt then
      reaper.ImGui_TextDisabled(ctx, "Target : " .. track_name(tt))
    else
      reaper.ImGui_TextDisabled(ctx,
        "Target : none  -  select a track in REAPER to generate.")
    end

    if ui_status ~= "" then
      reaper.ImGui_TextColored(ctx, COL_ACCENT, ui_status)
    end

    reaper.ImGui_End(ctx)
  end

  popTheme()

  if open then reaper.defer(loop) end
end

-- Leave nothing behind when the script closes: release any held note, hand the
-- track back as it was found, and store the pattern one last time so that a
-- window closed seconds after an edit still keeps it.
reaper.atexit(function()
  flush_pending_notes(true)
  if preview.on then preview_off() end
  autosave(state, true)
end)

reaper.defer(loop)
